pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address b, uint256 amtA, uint256 amtB) public {
        vm.assume(a != address(0) && b != address(0) && a != b);
        amtA = bound(amtA, 1, 100 ether);
        amtB = bound(amtB, 0, 100 ether);

        vm.deal(a, amtA);
        vm.prank(a);
        c.deposit{value: amtA}();

        vm.deal(b, amtB);
        vm.prank(b);
        c.deposit{value: amtB}();

        vm.prank(a);
        c.withdrawAll();

        // Rule: after a full withdrawal by any depositor, the contract's ether
        // balance equals the remaining outstanding credit of the other depositor.
        assertTrue(address(c).balance == c.credit(b));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1 wei, type(uint128).max);

        // actor deposits `amount`, contract holds it
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 balBefore = address(c).balance;

        // actor withdraws all outstanding credit
        vm.prank(actor);
        c.withdrawAll();

        // Rule: a completed withdrawal pays out exactly the caller's credit,
        // so the contract's ether balance shrinks by exactly that amount.
        assertTrue(address(c).balance == balBefore - amount);
    }
}

