// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(c).balance + type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll();

        // After a successful withdrawAll the caller's credit is consumed:
        // a second withdrawAll must succeed and transfer nothing.
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok && address(c).balance == 0);
    }
}

