pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        Actor actor = new Actor();
        vm.deal(address(actor), amount);
        actor.doDeposit(c, amount);
        bool ok1 = actor.doWithdraw(c);
        bool ok2 = actor.doWithdraw(c);
        assertTrue(ok1 && ok2 && address(c).balance == 0);
    }
}

contract Actor {
    function doDeposit(C c, uint256 amount) external payable {
        c.deposit{value: amount}();
    }
    function doWithdraw(C c) external returns (bool) {
        try c.withdrawAll() { return true; } catch { return false; }
    }
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 10 ether);

        // first cycle: deposit then withdraw everything
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();

        // second deposit: tracked balance must still equal real ETH balance
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        assertTrue(address(c).balance == c.balance());
    }
}
